public static int maxRegions(int N) {
  /*
   * Calculate the maximum number of regions that can be divided by N triangles.
   * The formula for calculating the number of regions is:
   * N + 1 - comparisons between triangles.
   */
  return N + 1 - (N * (N - 1)) / 2;
}

