public static int maxRegions(int N) {
    // Base case: If N is 1, the maximum number of regions is 2
    if (N == 1) {
        return 2;
    }

    // Recursive case: If N is greater than 1, the maximum number of regions is 2 plus the maximum number of regions for N - 1
    return 2 + maxRegions(N - 1);
}

