public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    int[][] visited = new int[n][n];
    visited[start[0]][start[1]] = 1;

    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    while (!queue.isEmpty()) {
        int[] curr = queue.poll();
        if (curr[0] == end[0] && curr[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] neighbor : getNeighbors(curr, paths, visited)) {
            if (visited[neighbor[0]][neighbor[1]] == 0) {
                visited[neighbor[0]][neighbor[1]] = 1;
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

private static int[][] getNeighbors(int[] curr, int[][] paths, int[][] visited) {
    List<int[]> neighbors = new ArrayList<>();
    for (int[] path : paths) {
        if (path[0] == curr[0] && path[1] == curr[1] && visited[path[0]][path[1]] == 0) {
            neighbors.add(path);
        }
    }
    return neighbors.toArray(new int[neighbors.size()][2]);
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (paths.length != n) {
        return "cannot be travelled";
    }
    dfs(start[0], start[1], end[0], end[1], paths);
    return "can be travelled";
}

private static void dfs(int currX, int currY, int targetX, int targetY, int[][] paths) {
    if (currX == targetX && currY == targetY) {
        return;
    }
    for (int[] path : paths) {
        int nextX = currX + path[0];
        int nextY = currY + path[1];
        if (nextX >= 0 && nextX < paths.length && nextY >= 0 && nextY < paths[0].length) {
            dfs(nextX, nextY, targetX, targetY, paths);
        }
    }
}

