public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Initialize a queue to perform BFS
  Queue<int[]> queue = new LinkedList<>();

  // Add the starting n-tersection to the queue
  queue.add(start);

  // Initialize a set to keep track of visited n-tersections
  Set<String> visited = new HashSet<>();

  // Keep track of the current n-tersection and its neighbors
  int[] current;
  int[] neighbors;

  // Iterate until the queue is empty
  while (!queue.isEmpty()) {
    // Get the current n-tersection and its neighbors
    current = queue.remove();
    neighbors = getNeighbors(current, n, paths);

    // Check if the ending n-tersection is in the neighbors list
    if (Arrays.asList(neighbors).contains(end)) {
      // If it is, return "can be travelled"
      return "can be travelled";
    }

    // Add the current n-tersection to the visited set
    visited.add(Arrays.toString(current));

    // Add the neighbors to the queue
    for (int[] neighbor : neighbors) {
      if (!visited.contains(Arrays.toString(neighbor))) {
        queue.add(neighbor);
      }
    }
  }

  // If the queue is empty and the ending n-tersection has not been found, return "cannot be travelled"
  return "cannot be travelled";
}

private static int[] getNeighbors(int[] current, int n, int[][] paths) {
  List<Integer> neighbors = new ArrayList<>();
  for (int[] path : paths) {
    if (path[0] == current[0] && path[1] == current[1]) {
      neighbors.add(path[2]);
    } else if (path[2] == current[0] && path[3] == current[1]) {
      neighbors.add(path[0]);
    }
  }
  return Arrays.copyOf(neighbors, neighbors.size(), int[].class);
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    return canTravelMazeHelper(start, end, paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelMazeHelper(int[] current, int[] end, int[][] paths, boolean[] visited) {
    if (Arrays.equals(current, end)) {
        return true;
    }
    visited[current[0] * n + current[1]] = true;
    for (int[] path : paths) {
        int nextX = current[0] + path[0];
        int nextY = current[1] + path[1];
        if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n && !visited[nextX * n + nextY]) {
            if (canTravelMazeHelper(new int[] { nextX, nextY }, end, paths, visited)) {
                return true;
            }
        }
    }
    return false;
}

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }
    int sumLengths = word1.length() + word2.length();
    int gcd = getGCD(sumLengths, commonLetters);
    int numerator = commonLetters / gcd;
    int denominator = sumLengths / gcd;
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

