    int len2 = word2.length();
    int divisor = len1 + len2 - commonLetters;
    int numerator = commonLetters;
    if (divisor == 0) {
        return "0";
    }
    int gcd = gcd(numerator, divisor);
    numerator /= gcd;
    divisor /= gcd;
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + divisor;
}

private static int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

