public boolean canArrange(int[] arr, int k) {
    // Edge case: array length not divisible by 2
    if (arr.length % 2 != 0) {
        return false;
    }

    // Edge case: k is not positive
    if (k <= 0) {
        return false;
    }

    // Initialize variables
    int n = arr.length / 2;
    int[] pairs = new int[n];
    int pairsCount = 0;

    // Iterate over the array and fill the pairs array
    for (int i = 0; i < arr.length; i++) {
        if (pairsCount < n) {
            pairs[pairsCount++] = arr[i];
        } else {
            // If the pairs array is full, check if it is possible to add the current element to an existing pair
            int remainingSum = 0;
            for (int j = 0; j < n; j++) {
                remainingSum += pairs[j];
            }
            if (arr[i] % k == 0 && remainingSum % k == 0) {
                pairs[0] += arr[i];
            } else {
                return false;
            }
        }
    }

    // Check if all pairs have a sum divisible by k
    for (int i = 0; i < n; i++) {
        if (pairs[i] % k != 0) {
            return false;
        }
    }

    return true;
}

