public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int[] counts = new int[k];
    for (int num : arr) {
        int key = num % k;
        if (key < 0) {
            key += k;
        }
        counts[key]++;
    }
    if (k % 2 == 1) {
        if (counts[0] % 2 == 1 || counts[k / 2] % 2 == 1) {
            return false;
        }
    } else {
        if (counts[0] % 2 == 1 || counts[k / 2] % 2 == 1 || counts[k - 1] % 2 == 1) {
            return false;
        }
    }

    int count = 0;
    for (int i = 1; i < k / 2; i++) {
        count += counts[i];
    }
    return count == n / 2;
}

