public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a queue to store the nodes in the tree
    Queue<Integer> queue = new LinkedList<>();

    // Add node 0 to the queue
    queue.offer(0);

    // Initialize a visited array to keep track of the visited nodes
    boolean[] visited = new boolean[n];

    // Initialize the minimum time to return to node 0
    int minTime = 0;

    // Iterate through the nodes in the queue
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int currentNode = queue.poll();

        // If the current node has an apple, update the minimum time
        if (hasApple[currentNode]) {
            minTime += 2;
        }

        // If the current node is not visited, mark it as visited and add its children to the queue
        if (!visited[currentNode]) {
            visited[currentNode] = true;
            for (int child : edges[currentNode]) {
                if (!visited[child]) {
                    queue.offer(child);
                }
            }
        }
    }

    // Return the minimum time required to collect all the apples and return to node 0
    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create a graph with the given edges
    Graph graph = new Graph(n);
    for (int[] edge : edges) {
        graph.addEdge(edge[0], edge[1]);
    }

    // Perform a breath-first search from node 0
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);
    boolean[] visited = new boolean[n];
    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (hasApple[current]) {
            return 1;
        }
        for (int neighbor : graph.getAdjacentNodes(current)) {
            if (!visited[neighbor]) {
                queue.add(neighbor);
                visited[neighbor] = true;
            }
        }
    }
    return 0;
}

public String sortString(String s) {
    if (s == null || s.length() < 2) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        char smallest = s.charAt(0);
        int smallestIndex = 0;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < smallest) {
                smallest = s.charAt(i);
                smallestIndex = i;
            }
        }
        result.append(smallest);
        s = s.substring(0, smallestIndex) + s.substring(smallestIndex + 1);
    }
    return result.toString();
}

