        char minChar = findMinChar(s);
        while (s.contains(String.valueOf(minChar))) {
            result.append(minChar);
            s = removeChar(s, minChar);
        }
        char maxChar = findMaxChar(s);
        while (s.contains(String.valueOf(maxChar))) {
            result.append(maxChar);
            s = removeChar(s, maxChar);
