public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int average = sum / nums.length;
    return anyPairSum(nums, average) != 0;
}

private int anyPairSum(int[] nums, int target) {
    for (int i = 0; i < nums.length; i++) {
        for (int j = i + 1; j < nums.length; j++) {
            if (nums[i] + nums[j] == target) {
                return 1;
            }
        }
    }
    return 0;
}

public boolean splitArraySameAverage(int[] nums) {
  int sum = 0;
  for (int num : nums) {
    sum += num;
  }
  double average = (double) sum / nums.length;
  int[][] dp = new int[nums.length][nums.length];
  for (int i = 0; i < nums.length; i++) {
    dp[i][i] = nums[i];
    for (int j = i + 1; j < nums.length; j++) {
      dp[i][j] = Math.max(dp[i][j - 1], dp[i + 1][j]);
      if (dp[i][j] * 2 == nums.length) {
        return true;
      }
    }
  }
  return false;
}

public boolean splitArraySameAverage(int[] nums) {
    double average = calculateAverage(nums);
    Arrays.sort(nums);
    int left = 0, right = nums.length - 1;
    while (left < right) {
        double leftSum = calculateSum(nums, left, right);
        double rightSum = calculateSum(nums, left + 1, right);
        if (leftSum == average && rightSum == average) {
            return true;
        }
        left++;
        right--;
    }
    return false;
}

private double calculateAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    return (double) sum / nums.length;
