        // Fill the dp array
        for (int i = 2; i <= costArray.length; i++) {
            dp[i] = Math.min(dp[i - 1] + costArray[i - 1], dp[i - 2] + costArray[i - 2]);
        }

        return dp[costArray.length];
    }

