public boolean hasAllCodes(String s, int k) {
    // Check if the length of the string s is valid
    if (s.length() < k) {
        return false;
    }

    // Compute the number of binary strings of length k
    int numBinaryStrings = (int) Math.pow(2, k);

    // Initialize a HashSet to store the binary strings
    Set<String> binaryStrings = new HashSet<>();

    // Iterate over the string s and extract all binary strings of length k
    for (int i = 0; i <= s.length() - k; i++) {
        String binaryString = s.substring(i, i + k);
        binaryStrings.add(binaryString);
    }

    // Check if the number of binary strings equals the expected number
    return binaryStrings.size() == numBinaryStrings;
}

public boolean hasAllCodes(String s, int k) {
    // Initialize a set to store all binary strings of length k
    Set<String> set = new HashSet<>();
    // Loop through the characters of the input string
    for (int i = 0; i <= s.length() - k; i++) {
        // Check if the substring of length k starting at the current index is in the set
        if (!set.contains(s.substring(i, i + k))) {
            // If the substring is not in the set, add it
            set.add(s.substring(i, i + k));
        }
    }
    // Return true if the set contains all binary strings of length k, and false otherwise
    return set.size() == (1 << k);
}

