int findMinFibonacciNumbers(int k) {
    int[] fibonacciNumbers = {1, 1};
    int index = 2;
    while (fibonacciNumbers[index - 1] + fibonacciNumbers[index - 2] <= k) {
        fibonacciNumbers[index] = fibonacciNumbers[index - 1] + fibonacciNumbers[index - 2];
        index++;
    }
    int count = 0;
    while (k > 0) {
        for (int i = index - 1; i >= 0; i--) {
            if (fibonacciNumbers[i] <= k) {
                k -= fibonacciNumbers[i];
                count++;
            }
        }
    }
    return count;
}

