public String getSmallestString(int n, int k) {
    String result = "";

    while (result.length() < n) {
        char nextChar = (char) (Math.min(26, k - result.length()) + 'a');
        result += nextChar;
        k -= nextChar - 'a' + 1;
    }

    return result;
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    while (k > 0) {
        int next = Math.min(k, 26);
        result[n - 1] = (char)('a' + next - 1);
        k -= next;
        n -= 1;
    }
    return new String(result);
}

