    if (n < 1 || k < 1) {
        return "";
    }
    List<Character> chars = new ArrayList<>();
    while (k > 0) {
        int charValue = Math.min(k, 26);
        chars.add((char) (charValue + 'a' - 1));
        k -= charValue;
    }
    Collections.sort(chars);
    return new String(chars.toArray(new Character[0]));
}

