    int[][] dp = new int[m][n];

    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            int length = 1;
            if (i > 0 && j > 0 && mat[i][j] == 1) {
                length = Math.min(Math.min(dp[i - 1][j - 1], dp[i - 1][j]), dp[i][j - 1]) + 1;
            }
            dp[i][j] = Math.max(dp[i][j], length);
            max = Math.max(max, dp[i][j]);
        }
    }

    return max;
}

public static int longestLine(int[][] mat) {
    int maxLength = 0;
    int currentLength = 0;
    int[][] directions = {{1, 0}, {0, 1}, {1, 1}, {1, -1}};

    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                currentLength = 1;
                for (int[] direction : directions) {
                    currentLength = checkLine(mat, i, j, direction, currentLength);
                }
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }

    return maxLength;
}

private static int checkLine(int[][] mat, int i, int j, int[] direction, int currentLength) {
    int x = i + direction[0];
    int y = j + direction[1];
    while (x >= 0 && x < mat.length && y >= 0 && y < mat[0].length && mat[x][y] == 1) {
        currentLength++;
        x += direction[0];
        y += direction[1];
    }
    return currentLength;
}

