public static int largestRectangleArea(int[] heights) {
    if (heights.length == 0) return 0;
    int largest = 0;
    Stack<Integer> stack = new Stack<>();
    int[] newHeights = new int[heights.length];
    System.arraycopy(heights, 0, newHeights, 0, heights.length);
    Arrays.sort(newHeights);
    for (int i = 0; i < newHeights.length; i++) {
        while (!stack.isEmpty() && newHeights[i] < newHeights[stack.peek()]) {
            int h = newHeights[stack.pop()];
            largest = Math.max(largest, h * (i - (stack.isEmpty() ? 0 : stack.peek() + 1)));
        }
        stack.push(i);
    }
    while (!stack.isEmpty()) {
        int h = newHeights[stack.pop()];
        largest = Math.max(largest, h * (newHeights.length - (stack.isEmpty() ? 0 : stack.peek() + 1)));
    }
    return largest;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    for (int i = 0; i < heights.length; i++) {
        int minHeight = Integer.MAX_VALUE;
        for (int j = i; j < heights.length; j++) {
            minHeight = Math.min(minHeight, heights[j]);
            maxArea = Math.max(maxArea, minHeight * (j - i + 1));
        }
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    Stack<Integer> stack = new Stack<>();
    int maxArea = 0;

    for (int i = 0; i < heights.length; i++) {
        while (!stack.empty() && heights[stack.peek()] > heights[i]) {
            int height = heights[stack.pop()];
            int width = (stack.empty() ? i : i - stack.peek() - 1);
            maxArea = Math.max(maxArea, height * width);
        }
        stack.push(i);
    }

    while (!stack.empty()) {
        int height = heights[stack.pop()];
        int width = (stack.empty() ? heights.length : heights.length - stack.peek() - 1);
        maxArea = Math.max(maxArea, height * width);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    if(heights == null || heights.length == 0) {
        return 0;
    }

    int largestArea = 0;

    for(int i = 0; i < heights.length; i++) {
        int barHeight = heights[i];
        if(i == 0) {
            largestArea = Math.max(largestArea, barHeight);
        } else if (i == heights.length - 1) {
            largestArea = Math.max(largestArea, barHeight);
        } else {
            int thisArea = Math.abs(barHeight - heights[i + 1]) * 1;
            int nextArea = Math.abs(barHeight - heights[i - 1]) * 1;
            largestArea = Math.max(largestArea, Math.abs(thisArea + nextArea));
        }
    }

    return largestArea;
}

public static int largestRectangleArea(int[] heights) {
    int area = 0;
    for (int i = 0; i < heights.length; i++) {
        int minHeight = heights[i];
        for (int j = i; j < heights.length; j++) {
            minHeight = Math.min(minHeight, heights[j]);
            area = Math.max(area, minHeight * (j - i + 1));
        }
    }
    return area;
}

