    // Rearrange the digits to form the smallest integer greater than n
    for (int i = digits.length - 1; i >= 0; i--) {
        if (digits[i] > n) {
            continue;
        }
        smallestInteger = digits[i];
        break;
    }

    return smallestInteger;
}

public static int[] toDigits(int n) {
    List<Integer> digits = new ArrayList<>();

    while (n > 0) {
        digits.add(n % 10);
        n /= 10;
    }

    return digits.toArray(new int[digits.size()]);
}

