private static boolean isCenterSymmetric(String number) {
        int middleIndex = number.length() / 2;
        for (int i = 0; i < middleIndex; i++) {
            if (number.charAt(i) != number.charAt(number.length() - i - 1)) {
                return false;
            }
        }
        return true;
    }

