bool isBoomerang(int[][] points) {
    // Check if the given array has exactly 3 points
    if (points.length != 3) {
        return false;
    }

    // Check if the three points are distinct
    if (points[0] == points[1] || points[0] == points[2] || points[1] == points[2]) {
        return false;
    }

    // Calculate the slope of the line joining the first and second points
    double slope1 = (double)(points[1][1] - points[0][1]) / (points[1][0] - points[0][0]);

    // Calculate the slope of the line joining the first and third points
    double slope2 = (double)(points[2][1] - points[0][1]) / (points[2][0] - points[0][0]);

    // Check if the slopes are equal
    if (slope1 == slope2) {
        return false;
    }

    // Check if the points are in the correct positions to form a boomerang
    if ((points[1][0] < points[0][0] && points[2][0] > points[0][0]) || (points[1][0] > points[0][0] && points[2][0] < points[0][0])) {
        return true;
    }

    return false;
}

public static boolean isBoomerang(int[][] points) {
        // Check if the given array has three points
        if (points.length != 3) {
            return false;
        }

        // Calculate the slopes of the lines connecting the points
        double slope1 = (double) (points[1][1] - points[0][1]) / (points[1][0] - points[0][0]);
        double slope2 = (double) (points[2][1] - points[1][1]) / (points[2][0] - points[1][0]);

        // Check if the slopes are equal
        if (slope1 == slope2) {
            return false;
        }

        // Check if the lines connecting the points are parallel
        if ((points[1][0] - points[0][0]) * (points[2][1] - points[1][1]) == (points[2][0] - points[1][0]) * (points[1][1] - points[0][1])) {
            return false;
        }

        return true;
    }

