public static int findNthUglyNumber(int n) {
		if (n < 1) return -1;
		int[] un = new int[n];
		int count = 1;
		un[0] = 1;
		for (int i = 2; i <= n; i++) {
		  int num = i;
		  int[] factors = findFactors(num);
		  if (factors.length == 0) {
			un[i-1] = num;
		  } else {
			int max = 0;
			for (int j = 0; j < factors.length; j++) {
			  if (factors[j] > max) {
				max = factors[j];
			  }
			}
			un[i-1] = max;
		  }
		}
		return un[n-1];
	}

private static int[] findFactors(int num) {
		List<Integer> factors = new ArrayList<>();
		for (int i = 2; i <= Math.sqrt(num); i++) {
		  if (num % i == 0) {
			factors.add(i);
			if (num / i != i) {
			  factors.add(num / i);
			}
		  }
		}
		return factors.toArray(new int[factors.size()]);
	}

public static int findNthUglyNumber(int n) {

        if(n <= 0) {
            return -1;
        }

        int[] uglyNumbers = new int[n];
        uglyNumbers[0] = 1;

        int index2 = 0, index3 = 0, index5 = 0, nextComposite;

        for(int i = 1; i < n; i++) {
            nextComposite = getNextComposite(uglyNumbers[index2],
                                             uglyNumbers[index3],
                                             uglyNumbers[index5]);

            index2 += nextComposite == uglyNumbers[index2]? 1 : 0;
            index3 += nextComposite == uglyNumbers[index3]? 1 : 0;
            index5 += nextComposite == uglyNumbers[index5]? 1 : 0;

            uglyNumbers[i] = nextComposite;
        }

        return uglyNumbers[n-1];
    }

public static int getNextComposite(int num2, int num3, int num5) {
        int min = Math.min(num2 * 2, Math.min(num3 * 3, num5 * 5));
        if(min == num2 * 2) {
            return 2;
        } else if(min == num3 * 3) {
            return 3;
        } else {
            return 5;
        }
    }

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }

    int i = 1;
    int count = 1;

    while (count < n) {
        i++;
        if (isUgly(i)) {
            count++;
        }
    }

    return i;
}

private static boolean isUgly(int num) {
    while (num % 2 == 0) {
        num /= 2;
    }
    while (num % 3 == 0) {
        num /= 3;
    }
    while (num % 5 == 0) {
        num /= 5;
    }
    return num == 1;
}

public static int findNthUglyNumber(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("n must be a positive integer.");
        }

        int[] uglyNumber = new int[n];
        uglyNumber[0] = 1;

        int i2 = 0, i3 = 0, i5 = 0;
        int factor2 = 2, factor3 = 3, factor5 = 5;

        for (int i = 1; i < n; i++) {
            int min = Math.min(factor2, Math.min(factor3, factor5));
            uglyNumber[i] = min;
            if (min == factor2) {
                i2++;
                factor2 = uglyNumber[i2] * 2;
            }
            if (min == factor3) {
                i3++;
                factor3 = uglyNumber[i3] * 3;
            }
            if (min == factor5) {
                i5++;
                factor5 = uglyNumber[i5] * 5;
            }
        }

        return uglyNumber[n - 1];
    }

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;

    for (int i = 1; i < n; i++) {
        int min = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = min;

        if (min == nextMultipleOf2) {
            i2++;
            nextMultipleOf2 = 2 * uglyNumbers[i2];
        }

        if (min == nextMultipleOf3) {
            i3++;
            nextMultipleOf3 = 3 * uglyNumbers[i3];
        }

        if (min == nextMultipleOf5) {
            i5++;
            nextMultipleOf5 = 5 * uglyNumbers[i5];
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int energy = 0;
    char previous = 0;
    int count = 0;
    for (char c : s.toCharArray()) {
        if (c == previous) {
            count++;
        } else {
            previous = c;
            count = 1;
        }
        if (count > energy) {
            energy = count;
        }
    }
    return energy;
}

public static int calculateEnergy(String s) {
        int n = s.length();
        if (n <= 1) return n;
        int energy = 0;
        char curr = s.charAt(0);
        int count = 1;
        for (int i = 1; i < n; i++) {
            if (s.charAt(i) == curr) {
                count++;
            } else {
                if (count > energy) {
                    energy = count;
                }
                curr = s.charAt(i);
                count = 1;
            }
        }
        return energy;
    }

