    int energy = 0;
    int current = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(current)) {
            current++;
            if (current > energy) {
                energy = current;
            }
        } else {
            current = 1;
        }
    }
    return energy;
}

public static int calculateEnergy(String s) {
  int maxLength = 0;
  int currentLength = 0;
  char previousChar = '';

  for (char c : s.toCharArray()) {
    if (c == previousChar) {
      currentLength++;
    } else {
      maxLength = Math.max(maxLength, currentLength);
      currentLength = 1;
    }
    previousChar = c;
  }

  return Math.max(maxLength, currentLength);
}

