public static int minPerfectSquareSum(int n) {

    int[] nums = {1, 4, 9, 16, 25, 36, 49, 64, 81, 100};
    Map<Integer, Integer> map = new HashMap<>();
    for(Integer i: nums){
        map.put(i, 1);
    }

    for(int i=2; i<=n; ++i){
        for(Integer j: nums){
            if(map.containsKey(i-j)){
                map.put(i, map.get(i-j)+1);
            }
        }
    }
    return map.get(n);
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 1;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            min = Math.min(min, dp[i - j * j] + 1);
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

